/**
 * A minimal ERC-20, compiled to bytecode ahead of time.
 *
 * The chain tests need a real token contract emitting real `Transfer` logs —
 * a mocked provider would only prove that the mock matches our assumptions,
 * which is precisely the thing worth doubting. Keeping the artefact here avoids
 * a solc toolchain in the test path.
 *
 * Source (solc 0.8.x, optimizer on):
 *
 *   contract TestToken {
 *     string public name = "Test USDT";
 *     string public symbol = "USDT";
 *     uint8  public decimals = 18;
 *     mapping(address => uint256) public balanceOf;
 *     event Transfer(address indexed from, address indexed to, uint256 value);
 *     constructor(uint256 supply) { balanceOf[msg.sender] = supply;
 *       emit Transfer(address(0), msg.sender, supply); }
 *     function transfer(address to, uint256 value) public returns (bool) {
 *       require(balanceOf[msg.sender] >= value, "insufficient");
 *       balanceOf[msg.sender] -= value; balanceOf[to] += value;
 *       emit Transfer(msg.sender, to, value); return true;
 *     }
 *   }
 */
export const ERC20_ABI = [
  'constructor(uint256 supply)',
  'event Transfer(address indexed from, address indexed to, uint256 value)',
  'function transfer(address to, uint256 value) returns (bool)',
  'function balanceOf(address) view returns (uint256)',
  'function decimals() view returns (uint8)',
];

export const ERC20_BYTECODE =
  '';
